// Some portions generated by Claude
/** SPARQL result rows to graph terms: labels, kinds and the triples of a ?source ?predicate ?target result. */
import type { Binding, SparqlValue } from "./explorer-types.ts";
import type { GraphNode } from "./graph-types.ts";
import { isSafeSparqlIri as isSafeRdfIri, isSparqlTerm, sparqlNodeId, type SparqlTerm } from "./rdf-terms.ts";
import { humanizeIri } from "./rdf-vocabulary.ts";

export const termAliases = {
  source: ["source", "s", "subject", "from"],
  predicate: ["predicate", "p", "property", "relation", "edge"],
  target: ["target", "o", "object", "to"],
};

const KNOWN_PREFIXES: ReadonlyArray<readonly [string, string]> = [
  ["http://www.wikidata.org/prop/direct/", "wdt:"],
  ["http://www.wikidata.org/prop/", "p:"],
  ["http://www.wikidata.org/entity/", "wd:"],
  ["http://schema.org/", "schema:"],
  ["http://www.w3.org/2000/01/rdf-schema#", "rdfs:"],
  ["http://www.w3.org/1999/02/22-rdf-syntax-ns#", "rdf:"],
  ["http://www.w3.org/2001/XMLSchema#", "xsd:"],
];

/** compactTerm runs for every term of every result row (600,000 times for a 300,000-statement graph). */
const compactTerms = new Map<string, string>();

export function compactTerm(value: string, limit = 26) {
  const key = limit === 26 ? value : `${limit}\u0000${value}`;
  const known = compactTerms.get(key);
  if (known !== undefined) return known;
  const compact = computeCompactTerm(value, limit);
  if (compactTerms.size >= 250_000) compactTerms.clear();
  compactTerms.set(key, compact);
  return compact;
}

function computeCompactTerm(value: string, limit: number) {
  const known = KNOWN_PREFIXES.find(([namespace]) => value.startsWith(namespace));
  if (known) {
    const compact = `${known[1]}${value.slice(known[0].length)}`;
    return compact.length > limit ? `${compact.slice(0, limit - 1)}…` : compact;
  }

  const wikidata = value.match(/\/([QP]\d+)$/);
  if (wikidata) return wikidata[1];

  // Only something with a scheme can be an IRI; parsing anything else as a URL only throws.
  if (value.startsWith("_:") || value.startsWith("\"") || !/^[A-Za-z][A-Za-z0-9+.-]*:/.test(value)) {
    return value.length > limit ? `${value.slice(0, limit - 1)}…` : value;
  }

  try {
    const parsed = new URL(value);
    const segment = decodeURIComponent(parsed.pathname.split("/").filter(Boolean).pop() || parsed.hostname);
    const fragment = decodeURIComponent(parsed.hash.slice(1));
    const compact = fragment || segment || parsed.hostname;
    return compact.length > limit ? `${compact.slice(0, limit - 1)}…` : compact;
  } catch {
    return value.length > limit ? `${value.slice(0, limit - 1)}…` : value;
  }
}

export function isSafeSparqlIri(value: string) {
  return isSafeRdfIri(value);
}

export function predicateLabel(predicate: string, supplied?: string) {
  if (supplied && supplied !== predicate && !/^https?:\/\//.test(supplied)) return supplied;
  // Until a label is loaded, the local name read as words ("worksFor" → "works for").
  return humanizeIri(predicate);
}

export function termKind(term?: SparqlValue): GraphNode["kind"] {
  if (!term || term.type === "uri") return "iri";
  return term.type === "bnode" ? "blank" : "literal";
}

export function findBindingValue(binding: Binding, aliases: string[]) {
  if (!binding || typeof binding !== "object") return undefined;
  for (const alias of aliases) {
    const exact = binding[alias];
    if (isSparqlTerm(exact)) return exact;
    const key = Object.keys(binding).find((candidate) => candidate.toLowerCase() === alias);
    if (key && isSparqlTerm(binding[key])) return binding[key];
  }
  return undefined;
}

export function findLabel(binding: Binding, role: "source" | "predicate" | "target") {
  const aliases = termAliases[role];
  for (const alias of aliases) {
    const candidate = findBindingValue(binding, [`${alias}Label`, `${alias}_label`, `${alias}Name`]);
    if (candidate) return candidate.value;
  }
  return undefined;
}

export function bindingsToTriples(bindings: Binding[]) {
  return bindings.flatMap((binding) => {
    const source = findBindingValue(binding, termAliases.source);
    const predicate = findBindingValue(binding, termAliases.predicate);
    const target = findBindingValue(binding, termAliases.target);

    if (
      !source ||
      !predicate ||
      !target ||
      !isSparqlTerm(source) ||
      !isSparqlTerm(predicate) ||
      !isSparqlTerm(target) ||
      (source.type === "uri" && !isSafeSparqlIri(source.value)) ||
      (target.type === "uri" && !isSafeSparqlIri(target.value)) ||
      predicate.type !== "uri" ||
      !isSafeSparqlIri(predicate.value)
    ) {
      return [];
    }

    const sourceId = sparqlNodeId(source as SparqlTerm);
    const targetId = sparqlNodeId(target as SparqlTerm);

    return [
      {
        source: sourceId,
        sourceValue: source.value,
        sourceLabel: findLabel(binding, "source") || compactTerm(source.value),
        sourceKind: termKind(source),
        sourceDatatype: source.datatype,
        sourceLanguage: source["xml:lang"],
        predicate: predicate.value,
        predicateLabel: predicateLabel(predicate.value, findLabel(binding, "predicate")),
        target: targetId,
        targetValue: target.value,
        targetLabel: findLabel(binding, "target") || compactTerm(target.value),
        targetKind: termKind(target),
        targetDatatype: target.datatype,
        targetLanguage: target["xml:lang"],
      },
    ];
  });
}

export function tripleEdgeId(source: string, predicate: string, target: string) {
  // JSON encoding keeps the three RDF terms unambiguous even when a lexical
  // value contains a delimiter such as NUL. Edge IDs are persisted in saved
  // workspaces, so this also avoids collisions during batched discovery.
  return JSON.stringify([source, predicate, target]);
}

/** The line under a term in tables: the IRI (compact), a literal's language or datatype, or "blank node". */
export function termCode(node: Pick<GraphNode, "id" | "kind" | "datatype" | "language"> | undefined, id = node?.id ?? "") {
  if (!node || node.kind === "iri") return compactTerm(id, 42);
  if (node.kind === "blank") return "blank node";
  if (node.language) return `@${node.language}`;
  return compactTerm(node.datatype || "http://www.w3.org/2001/XMLSchema#string", 42);
}
